-- Scalar subquery: each order next to the overall average
SELECT id, amount, (SELECT AVG(amount) FROM orders) AS avg_amount FROM orders;

-- IN with a list from a subquery
SELECT name FROM customers
WHERE id IN (SELECT customer_id FROM orders WHERE status = 'paid');

-- Correlated EXISTS: "is there at least one matching row?"
SELECT c.name FROM customers c
WHERE EXISTS (SELECT 1 FROM orders o
              WHERE o.customer_id = c.id AND o.status = 'paid');
